{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.File",
  "description": "A file attachment for multimodal input.",
  "type": "object",
  "properties": {
    "file_data": {
      "description": "Base64-encoded file data.",
      "type": [
        "string",
        "null"
      ]
    },
    "file_id": {
      "description": "The ID of a previously uploaded file.",
      "type": [
        "string",
        "null"
      ]
    },
    "filename": {
      "description": "The filename for display purposes.",
      "type": [
        "string",
        "null"
      ]
    },
    "file_url": {
      "description": "A URL to fetch the file from.",
      "type": [
        "string",
        "null"
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.AssistantToolCallFunctionExpression",
  "description": "Expression variant of [`AssistantToolCallFunction`] for dynamic content.",
  "type": "object",
  "properties": {
    "name": {
      "description": "The function name expression.",
      "$ref": "functions.expression.WithExpression.string"
    },
    "arguments": {
      "description": "The arguments expression.",
      "$ref": "functions.expression.WithExpression.string"
    }
  },
  "required": [
    "name",
    "arguments"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.WithExpression.Nullable_agent.completions.message.RichContentExpression",
  "description": "A value that can be either a literal or an expression.\n\nThis allows Function definitions to mix static values with dynamic\nexpressions. During compilation, expressions are evaluated while\nliteral values pass through unchanged.\n\n# Example\n\nLiteral value:\n```json\n\"hello world\"\n```\n\nJMESPath expression:\n```json\n{\"$jmespath\": \"input.greeting\"}\n```\n\nStarlark expression:\n```json\n{\"$starlark\": \"input['greeting']\"}\n```",
  "anyOf": [
    {
      "description": "An expression (JMESPath or Starlark) to evaluate.",
      "$ref": "functions.expression.Expression"
    },
    {
      "description": "A literal value.",
      "anyOf": [
        {
          "$ref": "agent.completions.message.RichContentExpression"
        },
        {
          "type": "null"
        }
      ]
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.DeveloperMessageExpression",
  "description": "Expression variant of [`DeveloperMessage`] for dynamic content.",
  "type": "object",
  "properties": {
    "content": {
      "description": "The message content expression.",
      "$ref": "functions.expression.WithExpression.agent.completions.message.SimpleContentExpression"
    },
    "name": {
      "description": "Optional name expression.",
      "anyOf": [
        {
          "$ref": "functions.expression.WithExpression.Nullable_string"
        },
        {
          "type": "null"
        }
      ]
    }
  },
  "required": [
    "content"
  ]
}
